 const regimes=[['fixed','Pevný'],['flexible','Pružný'],['rotating','Zmenový'],['part_time','Skrátený úväzok'],['individual','Individuálny']].map(([v,n])=>hrOption(v,n,p?.work_regime??'fixed')).join('');
 const full=(p?.name||'Nový zamestnanec');
