async function requests(){if(currentUser?.role==='employee')return employeeRequests();if(currentUser?.role==='manager')return managerRequests();if(currentUser?.role==='auditor')return auditorDashboard();const list=await api('/api/absences');$('#content').innerHTML='<div class="grid2"><div class="panel"><h3>Nová neprítomnosť</h3><form id="absenceForm"><label class="field"><span>Zamestnanec</span>'+choose()+'</label><label class="field"><span>Druh neprítomnosti</span><select name="kind">'+[['vacation','Dovolenka'],['doctor','Lekár'],['accompany','Sprevádzanie'],['doctor_unpaid','Lekár – neplatené'],['accompany_unpaid','Sprevádzanie – neplatené'],['sick','PN'],['ocr','OČR'],['paid_leave','Platené voľno'],['unpaid','Neplatené voľno'],['business_trip','Služobná cesta'],['training','Školenie'],['wedding','Svadba'],['funeral','Pohreb'],['blood_donation','Darovanie krvi'],['maternity','Materská'],['paternity','Otcovská'],['parental','Rodičovská']].map(([v,n])=>'<option value="'+v+'">'+n+'</option>').join('')+'</select></label><div class="form-grid"><label class="field"><span>Od</span><input name="start" type="date" value="'+localDate()+'" required></label><label class="field"><span>Do</span><input name="end" type="date" value="'+localDate()+'" required></label></div><label class="field"><span>Počet minút (iba pri čiastočnom dni)</span><input type="number" name="minutes" min="1" placeholder="napr. 120"></label><label class="field"><span>Poznámka</span><input name="note" maxlength="400"></label><button class="primary">Odoslať žiadosť</button></form></div><div class="panel"><h3>Schvaľovanie a história</h3><div class="scroll"><table><thead><tr><th>Zamestnanec</th><th>Typ</th><th>Dátum</th><th>Stav</th><th>Akcia</th></tr></thead><tbody>'+list.map(a=>'<tr><td>'+esc(employees.find(e=>e.id===a.employee_id)?.name||a.employee_id)+'</td><td>'+esc(a.kind)+'</td><td>'+a.start+' – '+a.end+'</td><td><span class="pill '+a.status+'">'+a.status+'</span></td><td>'+ (a.status==='pending'?'<div class="actions"><button class="secondary mini" data-approve="'+a.id+'">✓</button><button class="secondary mini danger" data-reject="'+a.id+'">✕</button></div>':'—')+'</td></tr>').join('')+'</tbody></table></div></div></div>';$('#absenceForm').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));p.employee_id=Number($('#empSelect').value);p.minutes=p.minutes?Number(p.minutes):null;try{await api('/api/absences',{method:'POST',body:JSON.stringify(p)});toast('Žiadosť bola založená');requests()}catch(e){toast(e.message,true)}};document.querySelectorAll('[data-approve],[data-reject]').forEach(x=>x.onclick=async()=>{try{await api('/api/absences/'+(x.dataset.approve||x.dataset.reject)+'/'+(x.dataset.approve?'approve':'reject'),{method:'POST'});toast('Stav žiadosti zmenený');requests()}catch(e){toast(e.message,true)}})}
async function shifts(){
const start=monthStart(),end=localDate(new Date(new Date().getFullYear(),new Date().getMonth()+1,0));
const list=await api('/api/shifts?start='+start+'&end='+end);
$('#content').innerHTML='<div class="grid2"><div class="panel"><h3>Naplánovať zmenu</h3><form id="shiftForm"><label class="field"><span>Zamestnanec</span>'+choose()+'</label><label class="field"><span>Deň zmeny</span><input type="date" name="day" value="'+localDate()+'" required></label><div class="form-grid"><label class="field"><span>Začiatok</span><input name="start_time" type="time" value="08:00"></label><label class="field"><span>Koniec</span><input name="end_time" type="time" value="16:00"></label><label class="field"><span>Plánované minúty</span><input name="planned_minutes" type="number" value="480" min="0" max="1440"></label><label class="field"><span>Poznámka</span><input name="note" maxlength="200"></label></div><button class="primary">Uložiť zmenu</button></form></div><div class="panel"><h3>Zmeny tento mesiac</h3><div class="scroll"><table><thead><tr><th>Deň</th><th>Zamestnanec</th><th>Čas</th><th>Plán</th></tr></thead><tbody>'+list.map(x=>'<tr><td>'+x.day+'</td><td>'+esc(employees.find(e=>e.id===x.employee_id)?.name||x.employee_id)+'</td><td>'+esc(x.start_time)+' – '+esc(x.end_time)+'</td><td>'+fmt(x.planned_minutes)+'</td></tr>').join('')+'</tbody></table></div></div></div><div class="panel"><h3>Generovanie cyklu dispečingu 24/7</h3><p class="intro">Vyber zamestnanca a obdobie. Cyklus D–N–V–V znamená denná, nočná, voľno, voľno. Počty minút musia zodpovedať internému rozvrhu a schváleným prestávkam.</p><form id="cycleForm"><div class="form-grid"><label class="field"><span>Zamestnanec</span>'+choose('cycleEmployee')+'</label><label class="field"><span>Cyklus</span><select name="cycle"><option value="D-N-V-V">D – N – V – V</option><option value="R-P-V-V">R – P – V – V</option><option value="D-D-N-N-V-V-V-V">D – D – N – N – V – V – V – V</option></select></label><label class="field"><span>Od</span><input type="date" name="start" value="'+start+'" required></label><label class="field"><span>Do</span><input type="date" name="end" value="'+end+'" required></label><label class="field"><span>Posun cyklu (dni)</span><input type="number" name="offset" min="0" max="365" value="0"></label><label class="field"><span>Plánované minúty za dennú/nočnú (orientačne)</span><input type="number" name="day_minutes" min="0" max="1440" value="720"></label><label class="field"><span>Plánované minúty nočnej</span><input type="number" name="night_minutes" min="0" max="1440" value="720"></label></div><label class="hr-active"><input type="checkbox" name="overwrite"> Prepísať už naplánované zmeny (bez potvrdenia nie)</label><p><button class="primary" type="submit">Vygenerovať zmeny</button></p></form></div><div class="notice">Saldo podľa zmien je informatívne. Nočné a cezpolnočné smeny a zákonné prestávky vyžadujú osobitný výpočet.</div>';
$('#shiftForm').onsubmit=async ev=>{ev.preventDefault();const p=Object.fromEntries(new FormData(ev.target));p.employee_id=Number($('#empSelect').value);p.planned_minutes=Number(p.planned_minutes);try{await api('/api/shifts',{method:'POST',body:JSON.stringify(p)});toast('Zmena uložená');shifts()}catch(e){toast(e.message,true)}};
$('#cycleForm').onsubmit=async ev=>{ev.preventDefault();const p=Object.fromEntries(new FormData(ev.target));p.employee_id=Number($('#cycleEmployee').value);p.offset=Number(p.offset);p.day_minutes=Number(p.day_minutes);p.night_minutes=Number(p.night_minutes);p.overwrite=ev.target.querySelector('[name="overwrite"]').checked;if(p.overwrite&&!confirm('Prepísať existujúce zmeny v období?'))return;try{const result=await api('/api/shifts/generate-cycle',{method:'POST',body:JSON.stringify(p)});toast('Vygenerované zmeny: '+result.created_or_updated);shifts()}catch(e){toast(e.message,true)}};
}
async function reports(){$('#content').innerHTML='<div class="panel"><h3>Výkazy a zostatky</h3><div class="toolbar"><label class="field"><span>Zamestnanec</span>'+choose()+'</label><label class="field"><span>Od</span><input id="reportFrom" type="date" value="'+monthStart()+'"></label><label class="field"><span>Do</span><input id="reportTo" type="date" value="'+localDate()+'"></label><button class="primary" id="loadReport">Zobraziť</button></div><div id="reportResult" class="muted">Vyber zamestnanca a obdobie.</div></div>';$('#loadReport').onclick=async()=>{try{const id=$('#empSelect').value,start=$('#reportFrom').value,end=$('#reportTo').value;const t=await api('/api/timesheet/'+id+'?start='+start+'&end='+end),b=await api('/api/balances/'+id+'/'+new Date(start).getFullYear()),saldo=await api('/api/saldo/'+id+'?start='+start+'&end='+end);$('#reportResult').innerHTML='<div class="notice">Saldo za zvolené obdobie: <strong>'+ (saldo.totals.saldo_minutes<0?'-':'+')+fmt(saldo.totals.saldo_minutes) +'</strong> | plán '+fmt(saldo.totals.planned_minutes)+' | započítané voľno '+fmt(saldo.totals.credited_minutes)+'</div><div class="stats"><div class="stat"><small>Odpracované</small><div class="value">'+fmt(t.total_worked_minutes)+'</div></div><div class="stat"><small>Dovolenka čerpaná</small><div class="value">'+fmt(b.vacation.used_minutes)+'</div></div><div class="stat"><small>Lekár čerpaný</small><div class="value">'+fmt(b.doctor.used_minutes)+'</div></div><div class="stat"><small>Sprevádzanie čerpané</small><div class="value">'+fmt(b.accompany.used_minutes)+'</div></div></div><div class="scroll"><table><thead><tr><th>Príchod</th><th>Odchod</th><th>Hrubý čas</th><th>Prestávka</th><th>Odpracované</th></tr></thead><tbody>'+t.pairs.map(x=>'<tr><td>'+esc(x.in)+'</td><td>'+esc(x.out)+'</td><td>'+fmt(x.gross_minutes)+'</td><td>'+fmt(x.break_minutes)+'</td><td>'+fmt(x.net_minutes)+'</td></tr>').join('')+'</tbody></table></div><p class="muted">'+t.warnings.map(esc).join(' · ')+'</p><p class="subtle">Referenčný ročný nárok na dovolenku: '+fmt(b.vacation.illustrative_full_year_minutes)+' – vyžaduje potvrdenie HR.</p>'}catch(e){toast(e.message,true)}}}
async function terminal(){
 const devices=await api('/api/devices');
 const items=devices.map(d=>'<tr><td>'+esc(d.name)+'</td><td>'+esc(d.location||'—')+'</td><td>'+esc(d.active?'Aktívny':'Deaktivovaný')+'</td><td>'+esc(d.last_seen?String(d.last_seen).slice(0,19):'—')+'</td><td>'+(d.active?'<button class="secondary mini" data-rotate-device="'+d.id+'">Nový kľúč</button> <button class="secondary mini" data-disable-device="'+d.id+'">Deaktivovať</button>':'—')+'</td></tr>').join('');
 $('#content').innerHTML='<div class="panel"><div class="section-top"><div><h3>RFID terminály BID</h3><span class="muted">Tablet alebo Raspberry Pi · vlastný bezpečnostný kľúč pre každé zariadenie</span></div><button class="primary" id="openKiosk">Otvoriť pípačku</button></div><div class="notice">Terminál používa HTTPS, idempotentné záznamy, vlastný kľúč a šifrovanú offline frontu do 72 hodín. Na zariadení treba nastaviť číslo terminálu a jeho tajný kľúč.</div><div class="scroll"><table><thead><tr><th>Terminál</th><th>Umiestnenie</th><th>Stav</th><th>Posledný kontakt</th><th>Akcie</th></tr></thead><tbody>'+items+'</tbody></table></div></div><div class="panel"><h3>Nový terminál</h3><form id="createDevice"><div class="form-grid"><label class="field"><span>Názov zariadenia</span><input name="name" required placeholder="Vstupná hala – tablet"></label><label class="field"><span>Umiestnenie</span><input name="location" placeholder="BID · vchod"></label><label class="field"><span>Voliteľná povolená IP adresa</span><input name="allowed_ip" placeholder="Nechaj prázdne, ak sa IP mení"></label></div><button class="primary" type="submit">Vytvoriť terminál</button></form><p class="subtle">Nový kľúč uvidíš iba raz. Starý kľúč po rotácii prestane fungovať a neodoslaná fronta na zariadení musí byť pred rotáciou synchronizovaná.</p></div>';
 $('#openKiosk').onclick=()=>window.open('/kiosk','_blank','noopener');
 $('#createDevice').onsubmit=async ev=>{ev.preventDefault();const p=Object.fromEntries(new FormData(ev.target));if(!p.allowed_ip)p.allowed_ip=null;try{const result=await api('/api/devices',{method:'POST',body:JSON.stringify(p)});prompt('ID terminálu: '+result.id+'. Tajný kľúč (zobrazuje sa len raz, odovzdaj bezpečne do kiosku):',result.device_key);toast('Terminál vytvorený');terminal()}catch(e){toast(e.message,true)}};
 document.querySelectorAll('[data-rotate-device]').forEach(btn=>btn.onclick=async()=>{if(!confirm('Rotácia kľúča zneplatní starý kľúč a nevysynchronizované dáta. Pokračovať?'))return;try{const d=await api('/api/devices/'+btn.dataset.rotateDevice+'/rotate',{method:'POST'});prompt('Nový kľúč terminálu '+d.device_id+' (zobrazuje sa len raz):',d.device_key);toast('Kľúč terminálu obnovený');terminal()}catch(e){toast(e.message,true)}});
 document.querySelectorAll('[data-disable-device]').forEach(btn=>btn.onclick=async()=>{if(!confirm('Deaktivovať terminál?'))return;try{await api('/api/devices/'+btn.dataset.disableDevice+'/disable',{method:'POST'});toast('Terminál deaktivovaný');terminal()}catch(e){toast(e.message,true)}});
}
